/*
 * yamlcage core.
 *
 * This file is the single source of truth for both module builds. It has no
 * runtime dependencies. The CommonJS build is generated by scripts/build-cjs.mjs.
 */

export const YAMLCAGE_VERSION = '1.0.0';

export const YAMLCAGE_ERROR_CODES = Object.freeze({
  ALIAS_FORBIDDEN: 'YAMLCAGE_ALIAS_FORBIDDEN',
  ANCHOR_FORBIDDEN: 'YAMLCAGE_ANCHOR_FORBIDDEN',
  UNSAFE_TAG: 'YAMLCAGE_UNSAFE_TAG',
  MERGE_KEY_FORBIDDEN: 'YAMLCAGE_MERGE_KEY_FORBIDDEN',
  DUPLICATE_KEY: 'YAMLCAGE_DUPLICATE_KEY',
  PROTOTYPE_KEY: 'YAMLCAGE_PROTOTYPE_KEY',
  MULTI_DOCUMENT: 'YAMLCAGE_MULTI_DOCUMENT',
  NON_FINITE_NUMBER: 'YAMLCAGE_NON_FINITE_NUMBER',
  MAX_DEPTH: 'YAMLCAGE_MAX_DEPTH',
  MAX_BYTES: 'YAMLCAGE_MAX_BYTES',
  MAX_NODES: 'YAMLCAGE_MAX_NODES',
  MAX_KEYS: 'YAMLCAGE_MAX_KEYS',
  MAX_SEQUENCE_LENGTH: 'YAMLCAGE_MAX_SEQUENCE_LENGTH',
  MAX_STRING_LENGTH: 'YAMLCAGE_MAX_STRING_LENGTH',
  MAX_KEY_LENGTH: 'YAMLCAGE_MAX_KEY_LENGTH',
  MAX_DOCUMENTS: 'YAMLCAGE_MAX_DOCUMENTS',
  MAX_ALIASES: 'YAMLCAGE_MAX_ALIASES',
  MAX_ALIAS_DEPTH: 'YAMLCAGE_MAX_ALIAS_DEPTH',
  MAX_EXPANDED_NODES: 'YAMLCAGE_MAX_EXPANDED_NODES',
  LONE_SURROGATE: 'YAMLCAGE_LONE_SURROGATE',
  INVALID_UTF8: 'YAMLCAGE_INVALID_UTF8',
  SYNTAX_ERROR: 'YAMLCAGE_SYNTAX_ERROR',
  NORWAY_AMBIGUITY_WARN: 'YAMLCAGE_NORWAY_AMBIGUITY_WARN',
  UNSAFE_INTEGER: 'YAMLCAGE_UNSAFE_INTEGER',
  BOM_REJECTED: 'YAMLCAGE_BOM_REJECTED',
  CONTROL_CHARACTER: 'YAMLCAGE_CONTROL_CHARACTER',
  INVALID_INPUT: 'YAMLCAGE_INVALID_INPUT',
  INVALID_OPTIONS: 'YAMLCAGE_INVALID_OPTIONS',
  UNDEFINED_ALIAS: 'YAMLCAGE_UNDEFINED_ALIAS',
  ALIAS_CYCLE: 'YAMLCAGE_ALIAS_CYCLE',
  DUPLICATE_ANCHOR: 'YAMLCAGE_DUPLICATE_ANCHOR',
  TAG_TYPE_MISMATCH: 'YAMLCAGE_TAG_TYPE_MISMATCH',
  UNSUPPORTED_VALUE: 'YAMLCAGE_UNSUPPORTED_VALUE',
  CYCLE_DETECTED: 'YAMLCAGE_CYCLE_DETECTED',
  MAX_OUTPUT_BYTES: 'YAMLCAGE_MAX_OUTPUT_BYTES',
  MAX_FINDINGS: 'YAMLCAGE_MAX_FINDINGS'
});

export const CODE = YAMLCAGE_ERROR_CODES;

export class YamlCageError extends Error {
  constructor(code, message, details) {
    super(code + ': ' + message);
    this.name = 'YamlCageError';
    this.code = code;
    this.reason = message;
    if (details && typeof details === 'object') {
      for (const key of Object.keys(details)) {
        if (details[key] !== undefined) this[key] = details[key];
      }
    }
  }

  toJSON() {
    const output = {
      name: this.name,
      code: this.code,
      reason: this.reason
    };
    for (const key of ['position', 'line', 'column', 'key', 'anchor', 'alias', 'tag', 'limit', 'actual', 'depth', 'document']) {
      if (this[key] !== undefined) output[key] = this[key];
    }
    return output;
  }
}

const ERROR = YAMLCAGE_ERROR_CODES;
const DANGEROUS_KEYS = new Set(['__proto__', 'constructor', 'prototype']);
const SAFE_CORE_TAGS = new Set(['!!str', '!!int', '!!float', '!!bool', '!!null', '!!map', '!!seq']);
const textEncoder = new TextEncoder();

export const YAML_CAGE_DEFAULT_OPTIONS = Object.freeze({
  maxBytes: 1048576,
  maxDepth: 32,
  maxKeys: 1000,
  maxSequenceLength: 10000,
  maxNodes: 50000,
  maxStringLength: 65536,
  maxKeyLength: 256,
  maxDocuments: 16,
  maxAliases: 25,
  maxAliasDepth: 4,
  maxExpandedNodes: 5000,
  maxOutputBytes: 1048576,
  maxFindings: 1024,
  allowAliases: false,
  allowMergeKeys: false,
  allowSafeTags: false,
  allowNonFinite: false,
  rejectUnsafeIntegers: false,
  rejectBom: true,
  warnNorwayScalars: true,
  strictNorwayScalars: false,
  allowMultiDocument: false
});

const OPTION_KEYS = new Set(Object.keys(YAML_CAGE_DEFAULT_OPTIONS));
const INTEGER_OPTION_KEYS = [
  'maxBytes',
  'maxDepth',
  'maxKeys',
  'maxSequenceLength',
  'maxNodes',
  'maxStringLength',
  'maxKeyLength',
  'maxDocuments',
  'maxAliases',
  'maxAliasDepth',
  'maxExpandedNodes',
  'maxOutputBytes',
  'maxFindings'
];
const BOOLEAN_OPTION_KEYS = [
  'allowAliases',
  'allowMergeKeys',
  'allowSafeTags',
  'allowNonFinite',
  'rejectUnsafeIntegers',
  'rejectBom',
  'warnNorwayScalars',
  'strictNorwayScalars',
  'allowMultiDocument'
];

function invalidOptions(message, key) {
  throw new YamlCageError(ERROR.INVALID_OPTIONS, message, { key });
}

function normalizeOptionsDetailed(input) {
  if (input === undefined || input === null) input = {};
  if (typeof input !== 'object' || Array.isArray(input)) {
    invalidOptions('options must be a plain object', 'options');
  }
  const providedKeys = Object.keys(input);
  const output = {};
  for (const key of providedKeys) {
    if (!OPTION_KEYS.has(key)) invalidOptions('unknown option', key);
  }
  for (const key of Object.keys(YAML_CAGE_DEFAULT_OPTIONS)) {
    output[key] = input[key] === undefined ? YAML_CAGE_DEFAULT_OPTIONS[key] : input[key];
  }
  for (const key of INTEGER_OPTION_KEYS) {
    const value = output[key];
    if (!Number.isSafeInteger(value) || value < 0) {
      invalidOptions(key + ' must be a non-negative safe integer', key);
    }
  }
  if (output.maxDepth < 1) invalidOptions('maxDepth must be at least 1', 'maxDepth');
  if (output.maxDocuments < 1) invalidOptions('maxDocuments must be at least 1', 'maxDocuments');
  if (output.maxKeys < 1) invalidOptions('maxKeys must be at least 1', 'maxKeys');
  if (output.maxSequenceLength < 1) invalidOptions('maxSequenceLength must be at least 1', 'maxSequenceLength');
  if (output.maxFindings < 1) invalidOptions('maxFindings must be at least 1', 'maxFindings');
  for (const key of BOOLEAN_OPTION_KEYS) {
    if (typeof output[key] !== 'boolean') invalidOptions(key + ' must be a boolean', key);
  }
  return { options: Object.freeze(output), providedKeys };
}

function normalizeOptions(input) {
  return normalizeOptionsDetailed(input).options;
}

function mergeNormalizedOptions(base, overrides) {
  const detailed = normalizeOptionsDetailed(overrides);
  if (detailed.providedKeys.length === 0) return base;
  const merged = { ...base };
  for (const key of detailed.providedKeys) merged[key] = detailed.options[key];
  return normalizeOptions(merged);
}

function utf8Length(value) {
  return textEncoder.encode(value).byteLength;
}

function makeNullObject() {
  return Object.create(null);
}

function byteDetails(limit, actual) {
  return { limit, actual };
}

function createContext(options) {
  return {
    options,
    nodes: 0,
    aliases: 0,
    expandedNodes: 0,
    maxDepthSeen: 0,
    warnings: [],
    warningsTruncated: 0,
    anchors: new Map(),
    openAnchors: [],
    openAnchorNames: new Set()
  };
}

function countNode(ctx, line, column) {
  ctx.nodes += 1;
  if (ctx.nodes > ctx.options.maxNodes) {
    throw new YamlCageError(ERROR.MAX_NODES, 'YAML node count limit exceeded', {
      line,
      column,
      limit: ctx.options.maxNodes,
      actual: ctx.nodes
    });
  }
}

function enterCollection(ctx, depth, line, column) {
  if (depth > ctx.maxDepthSeen) ctx.maxDepthSeen = depth;
  if (depth > ctx.options.maxDepth) {
    throw new YamlCageError(ERROR.MAX_DEPTH, 'YAML nesting depth limit exceeded', {
      line,
      column,
      depth,
      limit: ctx.options.maxDepth,
      actual: depth
    });
  }
}

function syntaxError(message, line, column, details) {
  throw new YamlCageError(ERROR.SYNTAX_ERROR, message, {
    line,
    column,
    ...(details || {})
  });
}

function isWhitespace(ch) {
  return ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r';
}

function isBidiControlCode(code) {
  return code === 0x061c ||
    code === 0x200e ||
    code === 0x200f ||
    (code >= 0x202a && code <= 0x202e) ||
    (code >= 0x2066 && code <= 0x206f);
}

function hasBidiControl(value) {
  for (let index = 0; index < value.length; index += 1) {
    if (isBidiControlCode(value.charCodeAt(index))) return true;
  }
  return false;
}

function validateCharacters(text) {
  for (let index = 0; index < text.length; index += 1) {
    const code = text.charCodeAt(index);
    if (code >= 0xd800 && code <= 0xdbff) {
      const next = text.charCodeAt(index + 1);
      if (next >= 0xdc00 && next <= 0xdfff) {
        index += 1;
        continue;
      }
      const position = positionAt(text, index);
      throw new YamlCageError(ERROR.LONE_SURROGATE, 'input contains a lone UTF-16 surrogate', {
        position: index,
        line: position.line,
        column: position.column
      });
    }
    if (code >= 0xdc00 && code <= 0xdfff) {
      const position = positionAt(text, index);
      throw new YamlCageError(ERROR.LONE_SURROGATE, 'input contains a lone UTF-16 surrogate', {
        position: index,
        line: position.line,
        column: position.column
      });
    }
    const allowed = code === 0x09 || code === 0x0a || code === 0x0d;
    if (!allowed && ((code >= 0x00 && code <= 0x1f) || (code >= 0x7f && code <= 0x9f))) {
      const position = positionAt(text, index);
      throw new YamlCageError(ERROR.CONTROL_CHARACTER, 'input contains a forbidden control character', {
        position: index,
        line: position.line,
        column: position.column
      });
    }
    if (isBidiControlCode(code)) {
      const position = positionAt(text, index);
      throw new YamlCageError(ERROR.CONTROL_CHARACTER, 'input contains a bidirectional control character', {
        position: index,
        line: position.line,
        column: position.column
      });
    }
  }
}

function positionAt(text, index) {
  let line = 1;
  let column = 1;
  const end = Math.min(index, text.length);
  for (let cursor = 0; cursor < end; cursor += 1) {
    if (text.charCodeAt(cursor) === 10) {
      line += 1;
      column = 1;
    } else {
      column += 1;
    }
  }
  return { line, column };
}

function normalizeBytesInput(input) {
  if (input instanceof Uint8Array) return input;
  if (input instanceof ArrayBuffer) return new Uint8Array(input);
  if (typeof SharedArrayBuffer !== 'undefined' && input instanceof SharedArrayBuffer) return new Uint8Array(input);
  if (ArrayBuffer.isView(input)) return new Uint8Array(input.buffer, input.byteOffset, input.byteLength);
  return null;
}

function decodeYamlBytes(input, options) {
  const bytes = normalizeBytesInput(input);
  if (bytes === null) {
    throw new YamlCageError(ERROR.INVALID_INPUT, 'input must be a string, Uint8Array, ArrayBuffer, SharedArrayBuffer, or ArrayBuffer view', {
      key: 'input'
    });
  }
  if (bytes.byteLength > options.maxBytes) {
    throw new YamlCageError(ERROR.MAX_BYTES, 'YAML byte size limit exceeded', byteDetails(options.maxBytes, bytes.byteLength));
  }
  const starts = (values) => values.every((value, index) => bytes[index] === value);
  if (starts([0xff, 0xfe, 0x00, 0x00]) || starts([0x00, 0x00, 0xfe, 0xff]) || starts([0xff, 0xfe]) || starts([0xfe, 0xff])) {
    throw new YamlCageError(ERROR.INVALID_UTF8, 'UTF-16 and UTF-32 byte order marks are rejected', { position: 0 });
  }
  let offset = 0;
  if (starts([0xef, 0xbb, 0xbf])) {
    if (options.rejectBom) {
      throw new YamlCageError(ERROR.BOM_REJECTED, 'UTF-8 byte order mark is rejected', { position: 0 });
    }
    offset = 3;
  }
  let text;
  try {
    text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(bytes.subarray(offset));
  } catch {
    throw new YamlCageError(ERROR.INVALID_UTF8, 'input is not valid UTF-8', { position: 0 });
  }
  return text;
}

function normalizeYamlInput(input, options) {
  let text;
  if (typeof input === 'string') {
    text = input;
  } else {
    text = decodeYamlBytes(input, options);
  }
  if (typeof input === 'string') {
    const size = utf8Length(input);
    if (size > options.maxBytes) {
      throw new YamlCageError(ERROR.MAX_BYTES, 'YAML byte size limit exceeded', byteDetails(options.maxBytes, size));
    }
    if (input.charCodeAt(0) === 0xfeff) {
      if (options.rejectBom) {
        throw new YamlCageError(ERROR.BOM_REJECTED, 'Unicode byte order mark is rejected', { position: 0 });
      }
      text = input.slice(1);
    }
  }
  validateCharacters(text);
  return text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
}

function trimEndSpacesAndTabs(text) {
  let end = text.length;
  while (end > 0 && (text[end - 1] === ' ' || text[end - 1] === '\t')) end -= 1;
  return end === text.length ? text : text.slice(0, end);
}

function trimEndFlowWhitespace(text) {
  let end = text.length;
  while (end > 0 && isWhitespace(text[end - 1])) end -= 1;
  return end === text.length ? text : text.slice(0, end);
}

function stripComment(text) {
  if (!text.includes('#') && !text.includes("'") && !text.includes('"')) return trimEndSpacesAndTabs(text);
  let inSingle = false;
  let inDouble = false;
  for (let index = 0; index < text.length; index += 1) {
    const ch = text[index];
    if (inSingle) {
      if (ch === "'") {
        if (text[index + 1] === "'") index += 1;
        else inSingle = false;
      }
      continue;
    }
    if (inDouble) {
      if (ch === '\\') {
        index += 1;
      } else if (ch === '"') {
        inDouble = false;
      }
      continue;
    }
    const previous = index === 0 ? '' : text[index - 1];
    const quoteStart = index === 0 || previous === ' ' || previous === '\t' || previous === ':' || previous === '-' || previous === '[' || previous === '{' || previous === ',';
    if (ch === "'" && quoteStart) {
      inSingle = true;
      continue;
    }
    if (ch === '"' && quoteStart) {
      inDouble = true;
      continue;
    }
    if (ch === '#' && (index === 0 || previous === ' ' || previous === '\t')) {
      return trimEndSpacesAndTabs(text.slice(0, index));
    }
  }
  return trimEndSpacesAndTabs(text);
}

function lineIsSignificant(raw) {
  return stripComment(raw).trim() !== '';
}

function splitDocuments(text) {
  const splitLines = text.split('\n');
  if (text.endsWith('\n')) splitLines.pop();
  const physicalLines = splitLines.map((source, index) => ({ text: source, line: index + 1 }));
  const documents = [];
  let current = [];
  let currentHasSignificant = false;
  let open = false;
  let ended = false;
  let currentStartLine = 1;
  let sawDocumentMarker = false;
  let sawYamlDirective = false;

  const pushDocument = () => {
    documents.push({ lines: current, startLine: currentStartLine });
    current = [];
    currentHasSignificant = false;
    open = false;
    sawYamlDirective = false;
  };

  for (const entry of physicalLines) {
    const raw = entry.text;
    const uncommented = stripComment(raw);
    const trimmed = uncommented.trim();
    const startsAtColumnZero = raw.startsWith('---') || raw.startsWith('...');
    if (startsAtColumnZero && raw.startsWith('---')) {
      if (trimmed !== '---') {
        syntaxError('inline content after a document start marker is outside the safe subset', entry.line, 1);
      }
      if (open || currentHasSignificant) pushDocument();
      current = [];
      currentHasSignificant = false;
      open = true;
      ended = false;
      sawDocumentMarker = true;
      currentStartLine = entry.line;
      continue;
    }
    if (startsAtColumnZero && raw.startsWith('...')) {
      if (trimmed !== '...') {
        syntaxError('inline content after a document end marker is outside the safe subset', entry.line, 1);
      }
      if (!open && !currentHasSignificant) {
        syntaxError('document end marker without a document', entry.line, 1);
      }
      pushDocument();
      ended = true;
      currentStartLine = entry.line + 1;
      continue;
    }
    if (raw.startsWith('%')) {
      if (/^%TAG(?:\s|$)/.test(raw)) {
        throw new YamlCageError(ERROR.UNSAFE_TAG, '%TAG directives are forbidden', { line: entry.line, column: 1 });
      }
      if (!/^%YAML[ \t]+1\.2[ \t]*$/.test(uncommented)) {
        syntaxError('unsupported YAML directive', entry.line, 1);
      }
      if (open || currentHasSignificant) syntaxError('YAML directives must precede their document', entry.line, 1);
      if (sawYamlDirective) syntaxError('duplicate YAML version directive', entry.line, 1);
      sawYamlDirective = true;
      continue;
    }
    if (ended) {
      if (lineIsSignificant(raw)) {
        syntaxError('content after a document end marker must start with a document marker', entry.line, 1);
      }
      continue;
    }
    current.push(entry);
    if (lineIsSignificant(raw)) {
      currentHasSignificant = true;
      open = true;
      if (!sawDocumentMarker && currentStartLine === 1 && current.length === 1) currentStartLine = entry.line;
    }
  }
  if (open || currentHasSignificant || documents.length === 0) {
    if (!ended || currentHasSignificant || open) pushDocument();
  }
  return documents;
}

function indentationOf(raw, lineNumber) {
  let indent = 0;
  while (indent < raw.length && raw[indent] === ' ') indent += 1;
  if (indent < raw.length && raw[indent] === '\t') {
    syntaxError('tab indentation is forbidden', lineNumber, indent + 1);
  }
  return indent;
}

function indentationForScan(raw) {
  let indent = 0;
  while (indent < raw.length && raw[indent] === ' ') indent += 1;
  return indent;
}

class LineCursor {
  constructor(lines) {
    this.lines = lines;
    this.index = 0;
    this.pending = [];
    this.cache = new Map();
  }

  inspectEntry(entry) {
    const key = entry.virtual === true ? null : entry.line;
    if (key !== null && this.cache.has(key)) return this.cache.get(key);
    const indent = entry.virtual === true ? entry.virtualIndent : indentationOf(entry.text, entry.line);
    const rawContent = entry.virtual === true ? entry.text : entry.text.slice(indent);
    const content = trimEndSpacesAndTabs(stripComment(rawContent));
    const inspected = {
      entry,
      indent,
      content,
      line: entry.line,
      blank: content.trim() === ''
    };
    if (key !== null) this.cache.set(key, inspected);
    return inspected;
  }

  peek() {
    if (this.pending.length > 0) return this.inspectEntry(this.pending[0]);
    while (this.index < this.lines.length) {
      const inspected = this.inspectEntry(this.lines[this.index]);
      if (!inspected.blank) return inspected;
      this.index += 1;
    }
    return null;
  }

  consume() {
    if (this.pending.length > 0) {
      return this.inspectEntry(this.pending.shift());
    }
    if (this.index < this.lines.length) {
      const inspected = this.inspectEntry(this.lines[this.index]);
      this.index += 1;
      return inspected;
    }
    return null;
  }

  pushVirtual(indent, content, line) {
    this.pending.unshift({ text: content, line, virtual: true, virtualIndent: indent });
  }
}

function splitMappingKey(content) {
  if (content.length === 0) return null;
  if (content[0] === "'" || content[0] === '"') {
    const parsed = scanQuotedToken(content, 0);
    if (parsed === null) return null;
    let cursor = parsed.end;
    while (cursor < content.length && (content[cursor] === ' ' || content[cursor] === '\t')) cursor += 1;
    if (content[cursor] !== ':') return null;
    if (cursor + 1 < content.length && content[cursor + 1] !== ' ' && content[cursor + 1] !== '\t') return null;
    let valueStart = cursor + 1;
    while (valueStart < content.length && (content[valueStart] === ' ' || content[valueStart] === '\t')) valueStart += 1;
    return {
      keyToken: content.slice(0, parsed.end),
      keyEnd: parsed.end,
      valueStart,
      colon: cursor,
      quoted: true
    };
  }
  if (content[0] === '-' || content[0] === '?' || content[0] === ':' || content[0] === '[' || content[0] === '{' || content[0] === '#') return null;
  for (let cursor = 0; cursor < content.length; cursor += 1) {
    const ch = content[cursor];
    if (ch === ':' && (cursor + 1 === content.length || content[cursor + 1] === ' ' || content[cursor + 1] === '\t')) {
      const keyToken = trimEndSpacesAndTabs(content.slice(0, cursor));
      if (keyToken.length === 0) return null;
      let valueStart = cursor + 1;
      while (valueStart < content.length && (content[valueStart] === ' ' || content[valueStart] === '\t')) valueStart += 1;
      return {
        keyToken,
        keyEnd: cursor,
        valueStart,
        colon: cursor,
        quoted: false
      };
    }
    if (ch === '[' || ch === '{' || ch === ']' || ch === '}' || ch === ',') return null;
  }
  return null;
}

function scanQuotedToken(text, start) {
  const quote = text[start];
  if (quote !== "'" && quote !== '"') return null;
  let cursor = start + 1;
  if (quote === "'") {
    while (cursor < text.length) {
      if (text[cursor] === '\n') return null;
      if (text[cursor] === "'") {
        if (text[cursor + 1] === "'") {
          cursor += 2;
          continue;
        }
        return { end: cursor + 1 };
      }
      cursor += 1;
    }
    return null;
  }
  while (cursor < text.length) {
    if (text[cursor] === '\n') return null;
    if (text[cursor] === '\\') {
      if (text[cursor + 1] === '\n') return null;
      cursor += 2;
      continue;
    }
    if (text[cursor] === '"') return { end: cursor + 1 };
    cursor += 1;
  }
  return null;
}

function decodeSingleQuoted(token, line, column) {
  if (token.length < 2 || token[0] !== "'" || token[token.length - 1] !== "'") {
    syntaxError('unterminated single-quoted scalar', line, column);
  }
  return token.slice(1, -1).replace(/''/g, "'");
}

function codePointFromHex(hex, expectedLength, line, column) {
  if (hex.length !== expectedLength || !/^[0-9a-fA-F]+$/.test(hex)) {
    syntaxError('invalid hexadecimal Unicode escape', line, column);
  }
  return Number.parseInt(hex, 16);
}

function decodeDoubleQuoted(token, line, column) {
  if (token.length < 2 || token[0] !== '"' || token[token.length - 1] !== '"') {
    syntaxError('unterminated double-quoted scalar', line, column);
  }
  const body = token.slice(1, -1);
  let output = '';
  for (let cursor = 0; cursor < body.length; cursor += 1) {
    const ch = body[cursor];
    if (ch !== '\\') {
      output += ch;
      continue;
    }
    cursor += 1;
    if (cursor >= body.length) syntaxError('trailing backslash in double-quoted scalar', line, column);
    const esc = body[cursor];
    if (esc === 'n') output += '\n';
    else if (esc === 't') output += '\t';
    else if (esc === 'r') output += '\r';
    else if (esc === '\\') output += '\\';
    else if (esc === '"') output += '"';
    else if (esc === '0') output += '\0';
    else if (esc === 'a') output += '\x07';
    else if (esc === 'b') output += '\b';
    else if (esc === 'f') output += '\f';
    else if (esc === 'v') output += '\v';
    else if (esc === 'e') output += '\x1b';
    else if (esc === 's') output += ' ';
    else if (esc === 'N') output += '\u0085';
    else if (esc === '_') output += '\u00a0';
    else if (esc === 'L') output += '\u2028';
    else if (esc === 'P') output += '\u2029';
    else if (esc === 'x' || esc === 'u' || esc === 'U') {
      const length = esc === 'x' ? 2 : esc === 'u' ? 4 : 8;
      const hex = body.slice(cursor + 1, cursor + 1 + length);
      const codePoint = codePointFromHex(hex, length, line, column);
      if (codePoint > 0x10ffff) syntaxError('Unicode escape is outside the Unicode range', line, column);
      output += String.fromCodePoint(codePoint);
      cursor += length;
    } else {
      syntaxError('unsupported escape in double-quoted scalar', line, column);
    }
  }
  validateScalarText(output, line, column);
  return output;
}

function validateScalarText(value, line, column) {
  for (let index = 0; index < value.length; index += 1) {
    const code = value.charCodeAt(index);
    if (code >= 0xd800 && code <= 0xdbff) {
      const next = value.charCodeAt(index + 1);
      if (next >= 0xdc00 && next <= 0xdfff) {
        index += 1;
        continue;
      }
      throw new YamlCageError(ERROR.LONE_SURROGATE, 'scalar contains a lone UTF-16 surrogate', { line, column });
    }
    if (code >= 0xdc00 && code <= 0xdfff) {
      throw new YamlCageError(ERROR.LONE_SURROGATE, 'scalar contains a lone UTF-16 surrogate', { line, column });
    }
    if (isBidiControlCode(code)) {
      throw new YamlCageError(ERROR.CONTROL_CHARACTER, 'scalar contains a bidirectional control character', { line, column });
    }
  }
}

function decodeKeyToken(keyToken, quoted, line, column) {
  if (!quoted) return keyToken;
  if (keyToken[0] === "'") return decodeSingleQuoted(keyToken, line, column);
  return decodeDoubleQuoted(keyToken, line, column);
}

function validateKey(key, ctx, line, column) {
  const length = utf8Length(key);
  if (length > ctx.options.maxKeyLength) {
    throw new YamlCageError(ERROR.MAX_KEY_LENGTH, 'mapping key length limit exceeded', {
      line,
      column,
      key,
      limit: ctx.options.maxKeyLength,
      actual: length
    });
  }
  if (DANGEROUS_KEYS.has(key)) {
    throw new YamlCageError(ERROR.PROTOTYPE_KEY, 'mapping key can mutate object prototypes', {
      line,
      column,
      key
    });
  }
}

function validateStringLength(value, ctx, line, column) {
  const length = utf8Length(value);
  if (length > ctx.options.maxStringLength) {
    throw new YamlCageError(ERROR.MAX_STRING_LENGTH, 'string scalar length limit exceeded', {
      line,
      column,
      limit: ctx.options.maxStringLength,
      actual: length
    });
  }
}

const YAML11_AMBIGUOUS_WORDS = new Set([
  'y', 'Y', 'yes', 'Yes', 'YES',
  'n', 'N', 'no', 'No', 'NO',
  'on', 'On', 'ON', 'off', 'Off', 'OFF'
]);

function noteNorwayScalar(raw, ctx, line, column) {
  if (!ctx.options.warnNorwayScalars || !YAML11_AMBIGUOUS_WORDS.has(raw)) return;
  const warning = {
    code: ERROR.NORWAY_AMBIGUITY_WARN,
    severity: 'warning',
    message: 'scalar stays a string in YAML 1.2 but is a boolean in YAML 1.1',
    line,
    column,
    value: raw
  };
  if (ctx.warnings.length < ctx.options.maxFindings) ctx.warnings.push(warning);
  else ctx.warningsTruncated += 1;
}

function parseIntegerText(raw) {
  const negative = raw.startsWith('-');
  const unsigned = raw.replace(/^[+-]/, '');
  if (!/^[0-9]+$/.test(unsigned)) return null;
  return negative ? -Number(unsigned) : Number(unsigned);
}

function hasNonZeroSignificantDigit(raw) {
  const mantissa = raw.replace(/^[+-]/, '').split(/[eE]/)[0];
  return /[1-9]/.test(mantissa);
}

function resolvePlainScalar(raw, ctx, line, column) {
  if (raw === '' || raw === 'null' || raw === 'Null' || raw === 'NULL' || raw === '~') return null;
  if (raw === 'true' || raw === 'True' || raw === 'TRUE') return true;
  if (raw === 'false' || raw === 'False' || raw === 'FALSE') return false;
  if (raw === 'NaN' || raw === 'nan' || raw === 'NAN') {
    if (!ctx.options.allowNonFinite) {
      throw new YamlCageError(ERROR.NON_FINITE_NUMBER, 'non-finite YAML numbers are forbidden', { line, column, actual: raw });
    }
    return Number.NaN;
  }
  if (raw === '.nan' || raw === '.NaN' || raw === '.NAN' || raw === '.inf' || raw === '.Inf' || raw === '.INF' || raw === '-.inf' || raw === '-.Inf' || raw === '-.INF' || raw === '+.inf' || raw === '+.Inf' || raw === '+.INF') {
    if (!ctx.options.allowNonFinite) {
      throw new YamlCageError(ERROR.NON_FINITE_NUMBER, 'non-finite YAML numbers are forbidden', { line, column, actual: raw });
    }
    if (raw.startsWith('.')) return raw[1] === 'n' || raw[1] === 'N' ? Number.NaN : Number.POSITIVE_INFINITY;
    return raw[0] === '-' ? Number.NEGATIVE_INFINITY : Number.POSITIVE_INFINITY;
  }
  if (/^[+-]?0x[0-9a-fA-F]+$/.test(raw)) {
    const negative = raw.startsWith('-');
    const digits = raw.replace(/^[+-]?0x/, '');
    let value = Number.parseInt(digits, 16);
    if (negative) value = -value;
    return validateIntegerResult(value, raw, ctx, line, column);
  }
  if (/^[+-]?0o[0-7]+$/.test(raw)) {
    const negative = raw.startsWith('-');
    const digits = raw.replace(/^[+-]?0o/, '');
    let value = Number.parseInt(digits, 8);
    if (negative) value = -value;
    return validateIntegerResult(value, raw, ctx, line, column);
  }
  if (/^[+-]?[0-9]+$/.test(raw)) {
    const value = parseIntegerText(raw);
    return validateIntegerResult(value, raw, ctx, line, column);
  }
  if (/^[+-]?(?:(?:[0-9]+\.[0-9]*)|(?:\.[0-9]+)|(?:[0-9]+[eE][+-]?[0-9]+)|(?:[0-9]+\.[0-9]*[eE][+-]?[0-9]+)|(?:\.[0-9]+[eE][+-]?[0-9]+))$/.test(raw)) {
    const value = Number(raw);
    if (!Number.isFinite(value)) {
      throw new YamlCageError(ERROR.NON_FINITE_NUMBER, 'numeric literal overflows the finite double range', { line, column, actual: raw });
    }
    return validateFloatResult(value, raw, ctx, line, column);
  }
  noteNorwayScalar(raw, ctx, line, column);
  validateStringLength(raw, ctx, line, column);
  return raw;
}

function validateIntegerResult(value, raw, ctx, line, column) {
  if (!Number.isFinite(value)) {
    throw new YamlCageError(ERROR.NON_FINITE_NUMBER, 'integer literal overflows the finite double range', { line, column, actual: raw });
  }
  if (ctx.options.rejectUnsafeIntegers && !Number.isSafeInteger(value)) {
    throw new YamlCageError(ERROR.UNSAFE_INTEGER, 'integer literal is outside the safe integer range', {
      line,
      column,
      actual: raw,
      limit: Number.MAX_SAFE_INTEGER
    });
  }
  return value;
}

function validateFloatResult(value, raw, ctx, line, column) {
  if (!Number.isFinite(value)) {
    if (!ctx.options.allowNonFinite) {
      throw new YamlCageError(ERROR.NON_FINITE_NUMBER, 'numeric literal overflows the finite double range', { line, column, actual: raw });
    }
    return value;
  }
  if (value === 0 && hasNonZeroSignificantDigit(raw)) {
    throw new YamlCageError(ERROR.NON_FINITE_NUMBER, 'nonzero numeric literal underflows the finite double range', { line, column, actual: raw });
  }
  if (ctx.options.rejectUnsafeIntegers && Number.isInteger(value) && !Number.isSafeInteger(value)) {
    throw new YamlCageError(ERROR.UNSAFE_INTEGER, 'integer literal is outside the safe integer range', {
      line,
      column,
      actual: raw,
      limit: Number.MAX_SAFE_INTEGER
    });
  }
  return value;
}

function parseTaggedScalar(tag, value, ctx, line, column, scalarInfo) {
  if (value !== null && typeof value === 'object') {
    throw new YamlCageError(ERROR.TAG_TYPE_MISMATCH, 'scalar YAML tags cannot be applied to collections', { line, column, tag });
  }
  if (tag === '!!str') {
    const output = scalarInfo && typeof scalarInfo.scalarText === 'string'
      ? scalarInfo.scalarText
      : value === null ? '' : String(value);
    validateStringLength(output, ctx, line, column);
    return output;
  }
  if (tag === '!!null') {
    if (value === null || value === 'null' || value === 'Null' || value === 'NULL' || value === '~' || value === '') return null;
    throw new YamlCageError(ERROR.TAG_TYPE_MISMATCH, '!!null scalar is not null', { line, column, tag });
  }
  if (tag === '!!bool') {
    if (value === true || value === 'true' || value === 'True' || value === 'TRUE') return true;
    if (value === false || value === 'false' || value === 'False' || value === 'FALSE') return false;
    throw new YamlCageError(ERROR.TAG_TYPE_MISMATCH, '!!bool scalar is not a YAML 1.2 boolean', { line, column, tag });
  }
  if (tag === '!!int') {
    if (typeof value === 'number' && Number.isInteger(value)) {
      return validateIntegerResult(value, String(value), ctx, line, column);
    }
    if (typeof value === 'string' && /^[+-]?(?:0x[0-9a-fA-F]+|0o[0-7]+|[0-9]+)$/.test(value)) {
      const negative = value.startsWith('-');
      const unsigned = value.replace(/^[+-]/, '');
      let parsed;
      if (/^0x/i.test(unsigned)) parsed = Number.parseInt(unsigned.slice(2), 16);
      else if (/^0o/i.test(unsigned)) parsed = Number.parseInt(unsigned.slice(2), 8);
      else parsed = Number(unsigned);
      const signed = negative ? -parsed : parsed;
      return validateIntegerResult(signed, value, ctx, line, column);
    }
    throw new YamlCageError(ERROR.TAG_TYPE_MISMATCH, '!!int scalar is not an integer', { line, column, tag });
  }
  if (tag === '!!float') {
    if (typeof value === 'number') return validateFloatResult(value, String(value), ctx, line, column);
    if (typeof value === 'string') {
      if (value === '.nan' || value === '.NaN' || value === '.NAN') {
        if (!ctx.options.allowNonFinite) throw new YamlCageError(ERROR.NON_FINITE_NUMBER, 'non-finite YAML numbers are forbidden', { line, column, actual: value });
        return Number.NaN;
      }
      if (value === '.inf' || value === '.Inf' || value === '.INF' || value === '+.inf' || value === '+.Inf' || value === '+.INF' || value === '-.inf' || value === '-.Inf' || value === '-.INF') {
        if (!ctx.options.allowNonFinite) throw new YamlCageError(ERROR.NON_FINITE_NUMBER, 'non-finite YAML numbers are forbidden', { line, column, actual: value });
        return value[0] === '-' ? Number.NEGATIVE_INFINITY : Number.POSITIVE_INFINITY;
      }
      if (/^[+-]?(?:(?:[0-9]+\.[0-9]*)|(?:\.[0-9]+)|(?:[0-9]+[eE][+-]?[0-9]+)|(?:[0-9]+\.[0-9]*[eE][+-]?[0-9]+)|(?:\.[0-9]+[eE][+-]?[0-9]+))$/.test(value)) {
        const parsed = Number(value);
        if (!Number.isFinite(parsed)) {
          throw new YamlCageError(ERROR.NON_FINITE_NUMBER, 'numeric literal overflows the finite double range', { line, column, actual: value });
        }
        return validateFloatResult(parsed, value, ctx, line, column);
      }
    }
    throw new YamlCageError(ERROR.TAG_TYPE_MISMATCH, '!!float scalar is not a float', { line, column, tag });
  }
  return value;
}

function validateTag(tag, ctx, line, column) {
  if (!ctx.options.allowSafeTags || !SAFE_CORE_TAGS.has(tag)) {
    throw new YamlCageError(ERROR.UNSAFE_TAG, 'explicit YAML tags are forbidden by policy', {
      line,
      column,
      tag
    });
  }
}

function applyTagAndAnchor(value, meta, ctx, line, column, scalarInfo) {
  let output = value;
  if (meta.tag !== null) {
    if (meta.tag === '!!map') {
      if (output === null || typeof output !== 'object' || Array.isArray(output)) {
        throw new YamlCageError(ERROR.TAG_TYPE_MISMATCH, '!!map node is not a mapping', { line, column, tag: meta.tag });
      }
    } else if (meta.tag === '!!seq') {
      if (!Array.isArray(output)) {
        throw new YamlCageError(ERROR.TAG_TYPE_MISMATCH, '!!seq node is not a sequence', { line, column, tag: meta.tag });
      }
    } else {
      output = parseTaggedScalar(meta.tag, output, ctx, line, column, scalarInfo);
    }
  }
  if (meta.anchorRecord) {
    finishAnchor(meta.anchorRecord, output, ctx, line, column);
    meta.anchorRecord = null;
  } else if (meta.anchor) {
    registerAnchor(meta.anchor, output, 0, ctx, line, column);
  }
  return output;
}

function beginAnchor(name, ctx, line, column) {
  if (!ctx.options.allowAliases) {
    throw new YamlCageError(ERROR.ANCHOR_FORBIDDEN, 'YAML anchors are forbidden by default', { line, column, anchor: name });
  }
  if (!/^[A-Za-z0-9_-]+$/.test(name)) syntaxError('anchor name is outside the safe subset', line, column);
  if (ctx.anchors.has(name) || ctx.openAnchorNames.has(name)) {
    throw new YamlCageError(ERROR.DUPLICATE_ANCHOR, 'duplicate YAML anchor name', { line, column, anchor: name });
  }
  const record = { name, nestedAliasDepth: 0, open: true, value: undefined, depth: 1 };
  ctx.openAnchors.push(record);
  ctx.openAnchorNames.add(name);
  return record;
}

function finishAnchor(record, value, ctx, line, column) {
  if (!record.open) return;
  record.open = false;
  record.value = value;
  record.depth = 1 + record.nestedAliasDepth;
  const index = ctx.openAnchors.indexOf(record);
  if (index !== -1) ctx.openAnchors.splice(index, 1);
  ctx.openAnchorNames.delete(record.name);
  ctx.anchors.set(record.name, record);
}

function registerAnchor(name, value, nestedAliasDepth, ctx, line, column) {
  const record = beginAnchor(name, ctx, line, column);
  record.nestedAliasDepth = nestedAliasDepth;
  finishAnchor(record, value, ctx, line, column);
}

function cloneValueLimited(value, ctx, line, column, aliasName) {
  const spend = () => {
    ctx.expandedNodes += 1;
    if (ctx.expandedNodes > ctx.options.maxExpandedNodes) {
      throw new YamlCageError(ERROR.MAX_EXPANDED_NODES, 'alias-expanded node count limit exceeded', {
        line,
        column,
        alias: aliasName,
        limit: ctx.options.maxExpandedNodes,
        actual: ctx.expandedNodes
      });
    }
  };
  if (value === null || typeof value !== 'object') {
    spend();
    return value;
  }
  const seen = new Set();
  const copyRoot = Array.isArray(value) ? [] : makeNullObject();
  spend();
  seen.add(value);
  const stack = [{ source: value, target: copyRoot }];
  while (stack.length > 0) {
    const frame = stack.pop();
    if (Array.isArray(frame.source)) {
      for (let index = 0; index < frame.source.length; index += 1) {
        const child = frame.source[index];
        if (child !== null && typeof child === 'object') {
          if (seen.has(child)) {
            throw new YamlCageError(ERROR.ALIAS_CYCLE, 'cyclic alias expansion is forbidden', { line, column, alias: aliasName });
          }
          seen.add(child);
          spend();
          const childCopy = Array.isArray(child) ? [] : makeNullObject();
          frame.target[index] = childCopy;
          stack.push({ source: child, target: childCopy });
        } else {
          spend();
          frame.target[index] = child;
        }
      }
    } else {
      for (const key of Object.keys(frame.source)) {
        const child = frame.source[key];
        if (child !== null && typeof child === 'object') {
          if (seen.has(child)) {
            throw new YamlCageError(ERROR.ALIAS_CYCLE, 'cyclic alias expansion is forbidden', { line, column, alias: aliasName });
          }
          seen.add(child);
          spend();
          const childCopy = Array.isArray(child) ? [] : makeNullObject();
          frame.target[key] = childCopy;
          stack.push({ source: child, target: childCopy });
        } else {
          spend();
          frame.target[key] = child;
        }
      }
    }
  }
  return copyRoot;
}

function resolveAlias(name, ctx, line, column) {
  if (!ctx.options.allowAliases) {
    throw new YamlCageError(ERROR.ALIAS_FORBIDDEN, 'YAML aliases are forbidden by default', { line, column, alias: name });
  }
  if (!/^[A-Za-z0-9_-]+$/.test(name)) syntaxError('alias name is outside the safe subset', line, column);
  ctx.aliases += 1;
  if (ctx.aliases > ctx.options.maxAliases) {
    throw new YamlCageError(ERROR.MAX_ALIASES, 'alias count limit exceeded', {
      line,
      column,
      alias: name,
      limit: ctx.options.maxAliases,
      actual: ctx.aliases
    });
  }
  if (ctx.openAnchorNames.has(name)) {
    throw new YamlCageError(ERROR.ALIAS_CYCLE, 'recursive alias reference is forbidden', { line, column, alias: name });
  }
  const record = ctx.anchors.get(name);
  if (!record) {
    throw new YamlCageError(ERROR.UNDEFINED_ALIAS, 'alias references an unknown anchor', { line, column, alias: name });
  }
  if (record.depth > ctx.options.maxAliasDepth) {
    throw new YamlCageError(ERROR.MAX_ALIAS_DEPTH, 'alias expansion depth limit exceeded', {
      line,
      column,
      alias: name,
      depth: record.depth,
      limit: ctx.options.maxAliasDepth
    });
  }
  for (const open of ctx.openAnchors) {
    if (record.depth > open.nestedAliasDepth) open.nestedAliasDepth = record.depth;
  }
  return cloneValueLimited(record.value, ctx, line, column, name);
}

function readModifiers(text, start, ctx, line, column) {
  let cursor = start;
  let anchor = null;
  let tag = null;
  while (cursor < text.length) {
    while (cursor < text.length && isWhitespace(text[cursor])) cursor += 1;
    const ch = text[cursor];
    if (ch === '&') {
      if (anchor !== null) syntaxError('a node cannot have two anchors', line, column + cursor);
      let end = cursor + 1;
      while (end < text.length && /[A-Za-z0-9_-]/.test(text[end])) end += 1;
      if (end === cursor + 1) syntaxError('empty anchor name', line, column + cursor);
      anchor = text.slice(cursor + 1, end);
      if (!ctx.options.allowAliases) {
        throw new YamlCageError(ERROR.ANCHOR_FORBIDDEN, 'YAML anchors are forbidden by default', { line, column: column + cursor, anchor });
      }
      if (end < text.length && !isWhitespace(text[end]) && !',]}'.includes(text[end])) {
        syntaxError('anchor must be separated from its node by whitespace', line, column + end);
      }
      cursor = end;
      continue;
    }
    if (ch === '!') {
      if (tag !== null) syntaxError('a node cannot have two tags', line, column + cursor);
      let end = cursor + 1;
      if (text.startsWith('!<', cursor)) {
        end = text.indexOf('>', cursor + 2);
        if (end === -1) syntaxError('unterminated verbatim tag', line, column + cursor);
        end += 1;
      } else {
        while (end < text.length && !isWhitespace(text[end]) && !',]}'.includes(text[end])) end += 1;
      }
      tag = text.slice(cursor, end);
      validateTag(tag, ctx, line, column + cursor);
      if (end < text.length && !isWhitespace(text[end]) && !',]}'.includes(text[end])) {
        syntaxError('tag must be separated from its node by whitespace', line, column + end);
      }
      cursor = end;
      continue;
    }
    break;
  }
  return { cursor, anchor, tag, anchorRecord: null };
}

function skipFlowWhitespace(text, cursor) {
  while (cursor < text.length && isWhitespace(text[cursor])) cursor += 1;
  return cursor;
}

function scanFlowPlain(text, start, stopChars, line, column) {
  let cursor = start;
  while (cursor < text.length) {
    const ch = text[cursor];
    if (stopChars.includes(ch)) break;
    if (stopChars !== '' && (ch === '[' || ch === '{' || ch === ']' || ch === '}' || ch === ',')) {
      syntaxError('flow collection punctuation must be inside a nested node or a quoted scalar', line, column + cursor);
    }
    cursor += 1;
  }
  return { raw: trimEndFlowWhitespace(text.slice(start, cursor)), end: cursor };
}

function scanScalarToken(text, cursor, stopChars, line, column) {
  const ch = text[cursor];
  if (ch === "'") {
    const scanned = scanQuotedToken(text, cursor);
    if (!scanned) syntaxError('unterminated single-quoted scalar', line, column + cursor);
    const token = text.slice(cursor, scanned.end);
    return { value: decodeSingleQuoted(token, line, column + cursor), end: scanned.end, plain: false };
  }
  if (ch === '"') {
    const scanned = scanQuotedToken(text, cursor);
    if (!scanned) syntaxError('unterminated double-quoted scalar', line, column + cursor);
    const token = text.slice(cursor, scanned.end);
    return { value: decodeDoubleQuoted(token, line, column + cursor), end: scanned.end, plain: false };
  }
  const plain = scanFlowPlain(text, cursor, stopChars, line, column);
  return { raw: plain.raw, end: plain.end, plain: true };
}

function parseScalarTokenValue(scanned, ctx, line, column) {
  countNode(ctx, line, column);
  if (!scanned.plain) {
    validateStringLength(scanned.value, ctx, line, column);
    return { value: scanned.value, scalarText: scanned.value };
  }
  return { value: resolvePlainScalar(scanned.raw, ctx, line, column), scalarText: scanned.raw };
}

function parseAliasToken(text, cursor, ctx, line, column) {
  let end = cursor + 1;
  while (end < text.length && /[A-Za-z0-9_-]/.test(text[end])) end += 1;
  if (end === cursor + 1) syntaxError('empty alias name', line, column + cursor);
  const name = text.slice(cursor + 1, end);
  return { value: resolveAlias(name, ctx, line, column + cursor), end, alias: name };
}

function finalizeMappingFrame(frame, ctx, line, column) {
  if (frame.merges.length === 0) return frame.object;
  const merged = makeNullObject();
  const mergedKeys = new Set();
  for (let index = frame.merges.length - 1; index >= 0; index -= 1) {
    const source = frame.merges[index];
    const sources = Array.isArray(source) ? source : [source];
    for (const entry of sources) {
      if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) {
        throw new YamlCageError(ERROR.MERGE_KEY_FORBIDDEN, 'merge key value must be a mapping or a sequence of mappings', { line, column });
      }
      for (const key of Object.keys(entry)) {
        if (!frame.explicitKeys.has(key) && !mergedKeys.has(key)) {
          mergedKeys.add(key);
          merged[key] = entry[key];
        }
      }
    }
  }
  const output = makeNullObject();
  let totalKeys = 0;
  for (const key of Object.keys(merged)) {
    output[key] = merged[key];
    totalKeys += 1;
  }
  for (const key of Object.keys(frame.object)) {
    output[key] = frame.object[key];
    totalKeys += 1;
  }
  if (totalKeys > ctx.options.maxKeys) {
    throw new YamlCageError(ERROR.MAX_KEYS, 'mapping key count limit exceeded', {
      line,
      column,
      limit: ctx.options.maxKeys,
      actual: totalKeys
    });
  }
  return output;
}

function assignMappingValue(frame, key, value, ctx, line, column) {
  if (key === '<<') {
    if (!ctx.options.allowMergeKeys) {
      throw new YamlCageError(ERROR.MERGE_KEY_FORBIDDEN, 'YAML merge keys are forbidden by default', { line, column, key });
    }
    if (frame.mergeSeen) {
      throw new YamlCageError(ERROR.DUPLICATE_KEY, 'duplicate merge key', { line, column, key });
    }
    frame.mergeSeen = true;
    frame.merges.push(value);
    return;
  }
  if (frame.explicitKeys.has(key)) {
    throw new YamlCageError(ERROR.DUPLICATE_KEY, 'duplicate mapping key', { line, column, key });
  }
  if (frame.explicitKeys.size >= ctx.options.maxKeys) {
    throw new YamlCageError(ERROR.MAX_KEYS, 'mapping key count limit exceeded', {
      line,
      column,
      key,
      limit: ctx.options.maxKeys,
      actual: frame.explicitKeys.size + 1
    });
  }
  frame.explicitKeys.add(key);
  frame.object[key] = value;
}

function parseFlow(text, start, ctx, depth, line, column) {
  const stack = [];
  let result;
  let haveResult = false;
  let cursor = start;

  const integrateValue = (value) => {
    if (stack.length === 0) {
      if (haveResult) syntaxError('multiple root nodes in flow value', line, column + cursor);
      result = value;
      haveResult = true;
      return;
    }
    const parent = stack[stack.length - 1];
    if (parent.type === 'seq') {
      if (parent.items.length >= ctx.options.maxSequenceLength) {
        throw new YamlCageError(ERROR.MAX_SEQUENCE_LENGTH, 'sequence length limit exceeded', {
          line,
          column: column + cursor,
          limit: ctx.options.maxSequenceLength,
          actual: parent.items.length + 1
        });
      }
      parent.items.push(value);
      parent.state = 'afterValue';
    } else {
      assignMappingValue(parent, parent.pendingKey, value, ctx, line, column + cursor);
      parent.pendingKey = null;
      parent.state = 'afterValue';
    }
  };

  const closeCollection = () => {
    const frame = stack.pop();
    let value = frame.type === 'seq' ? frame.items : finalizeMappingFrame(frame, ctx, line, column + cursor);
    value = applyTagAndAnchor(value, frame.meta, ctx, line, column + cursor);
    integrateValue(value);
  };

  while (true) {
    cursor = skipFlowWhitespace(text, cursor);
    if (stack.length === 0 && haveResult) {
      return { value: result, end: cursor };
    }
    if (cursor >= text.length) {
      if (stack.length !== 0) syntaxError('unterminated flow collection', line, column + cursor);
      syntaxError('missing flow value', line, column + cursor);
    }

    const frame = stack.length === 0 ? null : stack[stack.length - 1];
    const ch = text[cursor];

    if (frame && frame.type === 'seq' && frame.state === 'afterValue') {
      if (ch === ',') {
        cursor += 1;
        frame.state = 'expectValue';
        continue;
      }
      if (ch === ']') {
        cursor += 1;
        closeCollection();
        continue;
      }
      syntaxError('expected comma or closing bracket in flow sequence', line, column + cursor);
    }
    if (frame && frame.type === 'seq' && frame.state === 'expectFirstOrEnd' && ch === ']') {
      cursor += 1;
      closeCollection();
      continue;
    }
    if (frame && frame.type === 'map' && frame.state === 'afterValue') {
      if (ch === ',') {
        cursor += 1;
        frame.state = 'expectKey';
        continue;
      }
      if (ch === '}') {
        cursor += 1;
        closeCollection();
        continue;
      }
      syntaxError('expected comma or closing brace in flow mapping', line, column + cursor);
    }
    if (frame && frame.type === 'map' && frame.state === 'expectKeyOrEnd' && ch === '}') {
      cursor += 1;
      closeCollection();
      continue;
    }

    if (frame && frame.type === 'map' && (frame.state === 'expectKeyOrEnd' || frame.state === 'expectKey')) {
      if (ch === '[' || ch === '{' || ch === '*' || ch === '&' || ch === '!') {
        syntaxError('flow mapping keys must be plain or quoted scalars', line, column + cursor);
      }
      const scanned = scanScalarToken(text, cursor, ':}', line, column);
      countNode(ctx, line, column + cursor);
      if (scanned.plain && scanned.raw === '') {
        syntaxError('flow mapping keys must not be empty plain scalars', line, column + cursor);
      }
      const key = scanned.plain ? scanned.raw : scanned.value;
      validateKey(key, ctx, line, column + cursor);
      cursor = skipFlowWhitespace(text, scanned.end);
      if (text[cursor] !== ':') syntaxError('expected colon after flow mapping key', line, column + cursor);
      cursor += 1;
      frame.pendingKey = key;
      frame.state = 'expectValue';
      continue;
    }

    const inMapValue = frame && frame.type === 'map' && frame.state === 'expectValue';
    const inSeqValue = frame && frame.type === 'seq' && (frame.state === 'expectFirstOrEnd' || frame.state === 'expectValue');
    if (inMapValue && (ch === ',' || ch === '}')) {
      integrateValue(null);
      continue;
    }
    if (!frame || inMapValue || inSeqValue) {
      const meta = readModifiers(text, cursor, ctx, line, column);
      cursor = meta.cursor;
      cursor = skipFlowWhitespace(text, cursor);
      if (cursor >= text.length) syntaxError('missing node after YAML modifiers', line, column + cursor);
      if (meta.anchor !== null) meta.anchorRecord = beginAnchor(meta.anchor, ctx, line, column + cursor);
      const nodeStart = text[cursor];
      if (nodeStart === '[' || nodeStart === '{') {
        const nestedDepth = depth + stack.length;
        enterCollection(ctx, nestedDepth, line, column + cursor);
        countNode(ctx, line, column + cursor);
        const collectionFrame = nodeStart === '['
          ? { type: 'seq', items: [], state: 'expectFirstOrEnd', meta }
          : { type: 'map', object: makeNullObject(), explicitKeys: new Set(), merges: [], mergeSeen: false, pendingKey: null, state: 'expectKeyOrEnd', meta };
        stack.push(collectionFrame);
        cursor += 1;
        continue;
      }
      if (nodeStart === '|' || nodeStart === '>') {
        syntaxError('block scalar indicators are only valid immediately after a mapping key or sequence dash', line, column + cursor);
      }
      if ((nodeStart === ':' || nodeStart === '?') && (cursor + 1 === text.length || isWhitespace(text[cursor + 1]))) {
        syntaxError('explicit key indicator syntax is outside the safe subset', line, column + cursor);
      }
      if (nodeStart === '@' || nodeStart === '`') {
        syntaxError('reserved YAML indicator characters cannot start a plain scalar', line, column + cursor);
      }
      if (nodeStart === '*') {
        if (meta.anchor !== null || meta.tag !== null) {
          syntaxError('YAML aliases cannot carry anchors or tags in the safe subset', line, column + cursor);
        }
        const alias = parseAliasToken(text, cursor, ctx, line, column);
        countNode(ctx, line, column + cursor);
        cursor = alias.end;
        integrateValue(applyTagAndAnchor(alias.value, meta, ctx, line, column + cursor));
        continue;
      }
      const stopChars = frame && frame.type === 'seq' ? ',]' : frame && frame.type === 'map' ? ',}' : '';
      const scanned = scanScalarToken(text, cursor, stopChars, line, column);
      if (scanned.plain && scanned.raw === '' && !(inMapValue && (text[scanned.end] === ',' || text[scanned.end] === '}'))) {
        syntaxError('missing scalar value', line, column + cursor);
      }
      const scalar = parseScalarTokenValue(scanned, ctx, line, column + cursor);
      cursor = scanned.end;
      integrateValue(applyTagAndAnchor(scalar.value, meta, ctx, line, column + cursor, scalar));
      continue;
    }
    syntaxError('unexpected flow collection state', line, column + cursor);
  }
}

function parseInlineValue(text, ctx, depth, line, column) {
  const parsed = parseFlow(text, 0, ctx, depth, line, column);
  const end = skipFlowWhitespace(text, parsed.end);
  if (end !== text.length) syntaxError('trailing content after inline YAML value', line, column + end);
  return parsed.value;
}

function modifierOnlyParse(text, ctx, line, column) {
  const meta = readModifiers(text, 0, ctx, line, column);
  const rest = text.slice(meta.cursor).trim();
  return { meta, rest };
}

function blockScalarHeader(text) {
  if (!/^[|>](?:[+-]|[1-9]|[+-][1-9]|[1-9][+-])?$/.test(text.trim())) return null;
  const compact = text.trim();
  const style = compact[0];
  let chomping = 'clip';
  if (compact.includes('-')) chomping = 'strip';
  if (compact.includes('+')) chomping = 'keep';
  const digitMatch = compact.match(/[1-9]/);
  return { style, chomping, explicitIndent: digitMatch ? Number(digitMatch[0]) : null };
}

function parseBlockScalar(cursor, parentIndent, header, ctx, line, column) {
  countNode(ctx, line, column);
  const rows = [];
  let baseIndent = null;
  while (cursor.index < cursor.lines.length && cursor.pending.length === 0) {
    const entry = cursor.lines[cursor.index];
    const raw = entry.text;
    const blank = raw.trim() === '';
    const indent = indentationOf(raw, entry.line);
    if (!blank && indent <= parentIndent) break;
    if (!blank && baseIndent === null) {
      baseIndent = header.explicitIndent === null ? indent : parentIndent + header.explicitIndent;
      if (indent < baseIndent) syntaxError('block scalar indentation indicator exceeds the content indentation', entry.line, indent + 1);
    }
    if (!blank && baseIndent !== null && indent < baseIndent) {
      syntaxError('block scalar content is indented less than its first content line', entry.line, indent + 1);
    }
    cursor.index += 1;
    if (blank) {
      rows.push({ blank: true, text: '', moreIndented: false });
    } else {
      const remove = Math.min(baseIndent, raw.length);
      const text = raw.slice(remove);
      rows.push({ blank: false, text, moreIndented: indent > baseIndent });
    }
  }
  if (baseIndent === null) return '';
  let linear = rows.map((row) => row.text).join('\n') + '\n';
  if (header.style === '>') {
    let folded = '';
    let pendingBlank = 0;
    let previousMoreIndented = false;
    let first = true;
    for (const row of rows) {
      if (row.blank) {
        pendingBlank += 1;
        continue;
      }
      if (first) {
        folded = row.text;
        first = false;
      } else if (pendingBlank > 0) {
        folded += '\n'.repeat(pendingBlank + 1) + row.text;
      } else if (previousMoreIndented || row.moreIndented) {
        folded += '\n' + row.text;
      } else {
        folded += ' ' + row.text;
      }
      pendingBlank = 0;
      previousMoreIndented = row.moreIndented;
    }
    if (pendingBlank > 0) folded += '\n'.repeat(pendingBlank);
    linear = folded + '\n';
  }
  let output = linear;
  if (header.chomping === 'strip') output = output.replace(/\n+$/g, '');
  else if (header.chomping === 'clip') output = output.replace(/\n+$/g, '') + '\n';
  validateStringLength(output, ctx, line, column);
  return output;
}

function createFlowBalanceState() {
  return { depth: 0, started: false, invalid: false, inSingle: false, inDouble: false };
}

function feedFlowBalance(state, text) {
  for (let index = 0; index < text.length; index += 1) {
    const ch = text[index];
    if (state.inSingle) {
      if (ch === "'") {
        if (text[index + 1] === "'") index += 1;
        else state.inSingle = false;
      }
      continue;
    }
    if (state.inDouble) {
      if (ch === '\\') index += 1;
      else if (ch === '"') state.inDouble = false;
      continue;
    }
    if (ch === "'") state.inSingle = true;
    else if (ch === '"') state.inDouble = true;
    else if (ch === '[' || ch === '{') {
      state.depth += 1;
      state.started = true;
    } else if (ch === ']' || ch === '}') {
      state.depth -= 1;
      if (state.depth < 0) state.invalid = true;
    }
  }
}

function flowBalanceDone(state) {
  return state.started && state.depth === 0;
}

function collectInlineText(initial, parentIndent, cursor) {
  const firstNonspace = initial.trimStart()[0];
  if (firstNonspace !== '[' && firstNonspace !== '{') return initial;
  const chunks = [initial];
  const balance = createFlowBalanceState();
  feedFlowBalance(balance, initial);
  while (!flowBalanceDone(balance) && !balance.invalid && cursor.index < cursor.lines.length) {
    const entry = cursor.lines[cursor.index];
    cursor.index += 1;
    const continuation = stripComment(entry.text).trim();
    const addition = '\n' + continuation;
    chunks.push(addition);
    feedFlowBalance(balance, addition);
  }
  if (!flowBalanceDone(balance)) syntaxError('unterminated flow collection', null, null);
  return chunks.join('');
}

function isSequenceLine(content) {
  return content === '-' || content.startsWith('- ') || content.startsWith('-\t');
}

function sequenceRest(content) {
  if (content === '-') return '';
  return content.replace(/^-[ \t]+/, '');
}

function emptyBlockMeta() {
  return { tag: null, anchor: null, anchorRecord: null };
}

function assignBlockMappingValue(frame, key, value, ctx, line, column) {
  if (key === '<<') {
    if (!ctx.options.allowMergeKeys) {
      throw new YamlCageError(ERROR.MERGE_KEY_FORBIDDEN, 'YAML merge keys are forbidden by default', { line, column, key });
    }
    if (frame.mergeSeen) throw new YamlCageError(ERROR.DUPLICATE_KEY, 'duplicate merge key', { line, column, key });
    frame.mergeSeen = true;
    frame.merges.push(value);
    return;
  }
  if (frame.explicitKeys.has(key)) {
    throw new YamlCageError(ERROR.DUPLICATE_KEY, 'duplicate mapping key', { line, column, key });
  }
  if (frame.explicitKeys.size >= ctx.options.maxKeys) {
    throw new YamlCageError(ERROR.MAX_KEYS, 'mapping key count limit exceeded', {
      line,
      column,
      key,
      limit: ctx.options.maxKeys,
      actual: frame.explicitKeys.size + 1
    });
  }
  frame.explicitKeys.add(key);
  frame.object[key] = value;
}

function parseNode(cursor, ctx, depth, meta) {
  const stack = [];
  let startRequest = { depth, meta };
  let rootValue;
  let haveRootValue = false;

  const deliverValue = (value) => {
    if (stack.length === 0) {
      rootValue = value;
      haveRootValue = true;
      return;
    }
    const parent = stack[stack.length - 1];
    if (parent.type === 'map') {
      const pending = parent.pending;
      if (pending === null) syntaxError('internal mapping continuation missing a pending key', pending, null);
      assignBlockMappingValue(parent, pending.key, value, ctx, pending.line, pending.column);
      parent.pending = null;
    } else {
      parent.items.push(value);
      parent.pendingItem = false;
    }
  };

  const closeCollection = () => {
    const frame = stack[stack.length - 1];
    let value = frame.type === 'seq' ? frame.items : finalizeMappingFrame(frame, ctx, null, null);
    value = applyTagAndAnchor(value, frame.meta || emptyBlockMeta(), ctx, null, null);
    stack.pop();
    deliverValue(value);
  };

  const beginCollectionFrame = (sig, request) => {
    if (isSequenceLine(sig.content)) {
      enterCollection(ctx, request.depth, sig.line, sig.indent + 1);
      countNode(ctx, sig.line, sig.indent + 1);
      stack.push({
        type: 'seq',
        indent: sig.indent,
        depth: request.depth,
        meta: request.meta,
        items: [],
        pendingItem: false
      });
      return true;
    }
    if (splitMappingKey(sig.content)) {
      enterCollection(ctx, request.depth, sig.line, sig.indent + 1);
      countNode(ctx, sig.line, sig.indent + 1);
      stack.push({
        type: 'map',
        indent: sig.indent,
        depth: request.depth,
        meta: request.meta,
        object: makeNullObject(),
        explicitKeys: new Set(),
        merges: [],
        mergeSeen: false,
        pending: null
      });
      return true;
    }
    return false;
  };

  const startNestedNode = (request) => {
    const sig = cursor.peek();
    if (!sig) syntaxError('expected a YAML node', null, null);
    if (request.meta && request.meta.anchor !== null && !request.meta.anchorRecord) {
      request.meta.anchorRecord = beginAnchor(request.meta.anchor, ctx, sig.line, sig.indent + 1);
    }
    if (beginCollectionFrame(sig, request)) return;
    cursor.consume();
    const scalar = parseInlineValue(sig.content, ctx, request.depth, sig.line, sig.indent + 1);
    const value = applyTagAndAnchor(scalar, request.meta || emptyBlockMeta(), ctx, sig.line, sig.indent + 1);
    deliverValue(value);
  };

  const resolveAfterIndicator = (owner, rest, parentIndent, nodeDepth, line, column) => {
    const trimmed = rest.trim();
    if (trimmed === '') {
      const next = cursor.peek();
      if (next && (next.indent > parentIndent || (next.indent === parentIndent && isSequenceLine(next.content)))) {
        startRequest = { depth: nodeDepth + 1, meta: null };
        return false;
      }
      countNode(ctx, line, column);
      return true;
    }
    const scalarHeader = blockScalarHeader(trimmed);
    if (scalarHeader) {
      owner.immediateValue = parseBlockScalar(cursor, parentIndent, scalarHeader, ctx, line, column);
      return true;
    }
    const modifiers = modifierOnlyParse(trimmed, ctx, line, column);
    if (modifiers.rest === '' && (modifiers.meta.anchor !== null || modifiers.meta.tag !== null)) {
      const next = cursor.peek();
      if (next && next.indent > parentIndent) {
        startRequest = { depth: nodeDepth + 1, meta: modifiers.meta };
        return false;
      }
      countNode(ctx, line, column);
      owner.immediateValue = applyTagAndAnchor(null, modifiers.meta, ctx, line, column);
      return true;
    }
    const inline = collectInlineText(trimmed, parentIndent, cursor);
    owner.immediateValue = parseInlineValue(inline, ctx, nodeDepth + 1, line, column);
    return true;
  };

  while (!haveRootValue) {
    if (startRequest !== null) {
      const request = startRequest;
      startRequest = null;
      startNestedNode(request);
      continue;
    }

    const frame = stack[stack.length - 1];
    const sig = cursor.peek();
    if (frame.type === 'map') {
      if (!sig || sig.indent !== frame.indent || !splitMappingKey(sig.content)) {
        closeCollection();
        continue;
      }
      cursor.consume();
      const split = splitMappingKey(sig.content);
      const keyColumn = sig.indent + 1;
      const key = decodeKeyToken(split.keyToken, split.quoted, sig.line, keyColumn);
      validateKey(key, ctx, sig.line, keyColumn);
      countNode(ctx, sig.line, keyColumn);
      frame.pending = { key, line: sig.line, column: keyColumn };
      const rest = sig.content.slice(split.valueStart);
      const owner = { immediateValue: null };
      const immediate = resolveAfterIndicator(owner, rest, frame.indent, frame.depth, sig.line, sig.indent + split.valueStart + 1);
      if (immediate) {
        const value = owner.immediateValue;
        assignBlockMappingValue(frame, key, value, ctx, sig.line, keyColumn);
        frame.pending = null;
      }
      continue;
    }

    if (!sig || sig.indent !== frame.indent || !isSequenceLine(sig.content)) {
      closeCollection();
      continue;
    }
    cursor.consume();
    if (frame.items.length >= ctx.options.maxSequenceLength) {
      throw new YamlCageError(ERROR.MAX_SEQUENCE_LENGTH, 'sequence length limit exceeded', {
        line: sig.line,
        column: sig.indent + 1,
        limit: ctx.options.maxSequenceLength,
        actual: frame.items.length + 1
      });
    }
    const rest = sequenceRest(sig.content);
    let value;
    let hasImmediate = false;
    if (rest.trim() === '') {
      const next = cursor.peek();
      if (next && next.indent > frame.indent) {
        frame.pendingItem = true;
        startRequest = { depth: frame.depth + 1, meta: null };
      } else {
        countNode(ctx, sig.line, sig.indent + 1);
        value = null;
        hasImmediate = true;
      }
    } else {
      const trimmed = rest.trim();
      const scalarHeader = blockScalarHeader(trimmed);
      if (scalarHeader) {
        value = parseBlockScalar(cursor, frame.indent, scalarHeader, ctx, sig.line, sig.indent + 1);
        hasImmediate = true;
      } else {
        const modifiers = modifierOnlyParse(trimmed, ctx, sig.line, sig.indent + 2);
        if (modifiers.rest === '' && (modifiers.meta.anchor !== null || modifiers.meta.tag !== null)) {
          const next = cursor.peek();
          if (next && next.indent > frame.indent) {
            frame.pendingItem = true;
            startRequest = { depth: frame.depth + 1, meta: modifiers.meta };
          } else {
            countNode(ctx, sig.line, sig.indent + 2);
            value = applyTagAndAnchor(null, modifiers.meta, ctx, sig.line, sig.indent + 2);
            hasImmediate = true;
          }
        } else if (splitMappingKey(trimmed) || isSequenceLine(trimmed)) {
          cursor.pushVirtual(frame.indent + 2, trimmed, sig.line);
          frame.pendingItem = true;
          startRequest = { depth: frame.depth + 1, meta: null };
        } else {
          const inline = collectInlineText(trimmed, frame.indent, cursor);
          value = parseInlineValue(inline, ctx, frame.depth + 1, sig.line, sig.indent + 2);
          hasImmediate = true;
        }
      }
    }
    if (hasImmediate) frame.items.push(value);
  }
  return rootValue;
}

function parseDocument(document, ctx, documentIndex) {
  const cursor = new LineCursor(document.lines);
  ctx.anchors = new Map();
  ctx.openAnchors = [];
  ctx.openAnchorNames = new Set();
  const sig = cursor.peek();
  if (!sig) return null;
  const value = parseNode(cursor, ctx, 1, null);
  const trailing = cursor.peek();
  if (trailing) {
    syntaxError('unexpected trailing YAML content', trailing.line, trailing.indent + 1, { document: documentIndex });
  }
  return value;
}

function parseAllDocuments(text, options, ctx, rejectMultiDocument) {
  const documents = splitDocuments(text);
  if (documents.length > options.maxDocuments) {
    throw new YamlCageError(ERROR.MAX_DOCUMENTS, 'YAML document count limit exceeded', {
      limit: options.maxDocuments,
      actual: documents.length
    });
  }
  const values = [];
  const errors = [];
  for (let index = 0; index < documents.length; index += 1) {
    if (rejectMultiDocument && index > 0) {
      const error = new YamlCageError(ERROR.MULTI_DOCUMENT, 'multi-document YAML streams are forbidden in parseSafeYaml', {
        line: documents[index].startLine,
        column: 1,
        document: index + 1,
        actual: documents.length
      });
      errors.push({ error, document: index + 1 });
      values.push(undefined);
      break;
    }
    try {
      values.push(parseDocument(documents[index], ctx, index + 1));
    } catch (error) {
      if (!(error instanceof YamlCageError)) throw error;
      errors.push({ error, document: index + 1 });
      values.push(undefined);
    }
  }
  return { documents, values, errors };
}

function parseInputDocuments(input, optionsInput, rejectMultiDocument) {
  const options = normalizeOptions(optionsInput);
  const text = normalizeYamlInput(input, options);
  const ctx = createContext(options);
  const parsed = parseAllDocuments(text, options, ctx, rejectMultiDocument);
  return { options, text, ctx, ...parsed };
}

export function parseSafeYaml(input, options) {
  const parsed = parseInputDocuments(input, options, true);
  if (parsed.errors.length > 0) throw parsed.errors[0].error;
  if (parsed.values.length > 1) {
    throw new YamlCageError(ERROR.MULTI_DOCUMENT, 'multi-document YAML streams are forbidden in parseSafeYaml', {
      line: parsed.documents[1].startLine,
      column: 1,
      document: 2,
      actual: parsed.values.length
    });
  }
  return parsed.values[0];
}

export function parseSafeYamlBytes(input, options) {
  if (normalizeBytesInput(input) === null) {
    throw new YamlCageError(ERROR.INVALID_INPUT, 'parseSafeYamlBytes requires a Uint8Array, ArrayBuffer, SharedArrayBuffer, or ArrayBuffer view', {
      key: 'input'
    });
  }
  return parseSafeYaml(input, options);
}

export function parseSafeYamlDocuments(input, options) {
  const parsed = parseInputDocuments(input, options);
  if (parsed.errors.length > 0) throw parsed.errors[0].error;
  return parsed.values;
}

function scanQuotedEnd(text, start) {
  const quote = text[start];
  let cursor = start + 1;
  while (cursor < text.length) {
    if (quote === "'") {
      if (text[cursor] === "'") {
        if (text[cursor + 1] === "'") cursor += 2;
        else return cursor + 1;
      } else {
        cursor += 1;
      }
    } else {
      if (text[cursor] === '\\') cursor += 2;
      else if (text[cursor] === '"') return cursor + 1;
      else cursor += 1;
    }
  }
  return text.length;
}

function pushScanFinding(findings, seen, finding) {
  const key = finding.code + '|' + finding.line + '|' + finding.column + '|' + (finding.tag || finding.anchor || finding.alias || finding.key || '');
  if (seen.has(key)) return;
  if (findings.length >= seen.maxFindings) {
    seen.dropped += 1;
    return;
  }
  seen.add(key);
  findings.push(finding);
}

function scanModifierToken(text, cursor, findings, seen, options, line, columnOffset) {
  const ch = text[cursor];
  if (ch === '&' || ch === '*') {
    let end = cursor + 1;
    while (end < text.length && /[A-Za-z0-9_-]/.test(text[end])) end += 1;
    const name = text.slice(cursor + 1, end);
    if (name.length > 0 && !options.allowAliases) {
      pushScanFinding(findings, seen, {
        code: ch === '&' ? ERROR.ANCHOR_FORBIDDEN : ERROR.ALIAS_FORBIDDEN,
        severity: 'error',
        message: ch === '&' ? 'YAML anchors are forbidden by default' : 'YAML aliases are forbidden by default',
        line,
        column: columnOffset + cursor,
        [ch === '&' ? 'anchor' : 'alias']: name
      });
    }
    return { end, modifier: true, alias: ch === '*' };
  }
  if (ch === '!') {
    let end = cursor + 1;
    if (text.startsWith('!<', cursor)) {
      const close = text.indexOf('>', cursor + 2);
      end = close === -1 ? text.length : close + 1;
    } else {
      while (end < text.length && !isWhitespace(text[end]) && !',]}'.includes(text[end])) end += 1;
    }
    const tag = text.slice(cursor, end);
    if (!options.allowSafeTags || !SAFE_CORE_TAGS.has(tag)) {
      pushScanFinding(findings, seen, {
        code: ERROR.UNSAFE_TAG,
        severity: 'error',
        message: 'explicit YAML tags are forbidden by policy',
        line,
        column: columnOffset + cursor,
        tag
      });
    }
    return { end, modifier: true, alias: false };
  }
  return null;
}

function scanInlineThreats(text, flow, findings, seen, options, line, columnOffset) {
  let cursor = 0;
  let nodeStart = flow.depth === 0;
  while (cursor < text.length) {
    const ch = text[cursor];
    if (isWhitespace(ch)) {
      cursor += 1;
      continue;
    }
    if ((ch === "'" || ch === '"') && (flow.depth > 0 || nodeStart)) {
      cursor = scanQuotedEnd(text, cursor);
      nodeStart = false;
      flow.afterSeparator = false;
      continue;
    }
    if (flow.depth === 0) {
      if (!nodeStart) break;
      const modifier = scanModifierToken(text, cursor, findings, seen, options, line, columnOffset);
      if (modifier) {
        cursor = modifier.end;
        nodeStart = !modifier.alias;
        continue;
      }
      if (ch === '[' || ch === '{') {
        flow.depth += 1;
        flow.afterSeparator = true;
        cursor += 1;
        nodeStart = false;
        continue;
      }
      break;
    }

    if (ch === '[' || ch === '{') {
      flow.depth += 1;
      flow.afterSeparator = true;
      cursor += 1;
      continue;
    }
    if (ch === ']' || ch === '}') {
      flow.depth -= 1;
      flow.afterSeparator = false;
      cursor += 1;
      continue;
    }
    if (ch === ',' || ch === ':') {
      flow.afterSeparator = true;
      cursor += 1;
      continue;
    }
    if ((ch === '&' || ch === '*' || ch === '!') && flow.afterSeparator) {
      const modifier = scanModifierToken(text, cursor, findings, seen, options, line, columnOffset);
      if (modifier) {
        cursor = modifier.end;
        flow.afterSeparator = !modifier.alias;
        continue;
      }
    }
    flow.afterSeparator = false;
    cursor += 1;
  }
}

function scanBlockKey(content, findings, seen, line, indent, options) {
  const split = splitMappingKey(content);
  if (!split) return null;
  let key;
  try {
    key = decodeKeyToken(split.keyToken, split.quoted, line, indent + 1);
  } catch {
    return split;
  }
  if (DANGEROUS_KEYS.has(key)) {
    pushScanFinding(findings, seen, {
      code: ERROR.PROTOTYPE_KEY,
      severity: 'error',
      message: 'mapping key can mutate object prototypes',
      line,
      column: indent + 1,
      key
    });
  }
  if (key === '<<' && !options.allowMergeKeys) {
    pushScanFinding(findings, seen, {
      code: ERROR.MERGE_KEY_FORBIDDEN,
      severity: 'error',
      message: 'YAML merge keys are forbidden by default',
      line,
      column: indent + 1,
      key
    });
  }
  return split;
}

function scanDocumentThreats(document, documentIndex, findings, seen, options) {
  const flow = { depth: 0, afterSeparator: true };
  let blockScalarParent = null;
  for (const entry of document.lines) {
    const raw = entry.text;
    if (raw.startsWith('%TAG')) {
      pushScanFinding(findings, seen, {
        code: ERROR.UNSAFE_TAG,
        severity: 'error',
        message: '%TAG directives are forbidden',
        line: entry.line,
        column: 1,
        document: documentIndex
      });
      continue;
    }
    const indent = indentationForScan(raw);
    if (blockScalarParent !== null) {
      if (raw.trim() === '' || indent > blockScalarParent) continue;
      blockScalarParent = null;
    }
    const content = trimEndSpacesAndTabs(stripComment(raw.slice(indent)));
    if (content.trim() === '') continue;
    if (flow.depth > 0) {
      scanInlineThreats(content, flow, findings, seen, options, entry.line, indent + 1);
      continue;
    }

    let valueText = null;
    let valueColumn = indent + 1;
    if (isSequenceLine(content)) {
      const rest = sequenceRest(content).trim();
      valueText = rest;
      valueColumn = indent + 2;
      const compactSplit = splitMappingKey(rest);
      if (compactSplit) {
        scanBlockKey(rest, findings, seen, entry.line, indent + 2, options);
        valueText = rest.slice(compactSplit.valueStart).trim();
        valueColumn = indent + 2 + compactSplit.valueStart;
      }
    } else {
      const split = scanBlockKey(content, findings, seen, entry.line, indent, options);
      if (split) {
        valueText = content.slice(split.valueStart).trim();
        valueColumn = indent + split.valueStart + 1;
      } else {
        valueText = content.trim();
      }
    }
    if (valueText !== null && valueText !== '') {
      const header = blockScalarHeader(valueText);
      if (header) {
        blockScalarParent = indent;
        continue;
      }
      scanInlineThreats(valueText, flow, findings, seen, options, entry.line, valueColumn);
    }
  }
}

function scanYamlThreats(documents, options) {
  const findings = [];
  const seen = new Set();
  seen.maxFindings = options.maxFindings;
  seen.dropped = 0;
  for (let index = 0; index < documents.length; index += 1) {
    scanDocumentThreats(documents[index], index + 1, findings, seen, options);
  }
  return { findings, dropped: seen.dropped };
}

function freezeFindings(findings) {
  return Object.freeze(findings.map((finding) => Object.freeze({ ...finding })));
}

function deepFreeze(value, seen = new Set()) {
  if (value === null || typeof value !== 'object' || seen.has(value)) return value;
  seen.add(value);
  if (Array.isArray(value)) {
    for (const item of value) deepFreeze(item, seen);
  } else {
    for (const key of Object.keys(value)) deepFreeze(value[key], seen);
  }
  return Object.freeze(value);
}

function findingFromError(error, document) {
  return {
    code: error.code,
    severity: 'error',
    message: error.reason,
    line: error.line,
    column: error.column,
    document,
    key: error.key,
    anchor: error.anchor,
    alias: error.alias,
    tag: error.tag,
    limit: error.limit,
    actual: error.actual,
    depth: error.depth
  };
}

export function auditYaml(input, options) {
  let normalized;
  try {
    normalized = normalizeOptions(options);
  } catch (error) {
    throw error;
  }
  const findings = [];
  let text;
  let byteSize = 0;
  try {
    if (typeof input === 'string') byteSize = utf8Length(input);
    else {
      const bytes = normalizeBytesInput(input);
      byteSize = bytes ? bytes.byteLength : 0;
    }
    text = normalizeYamlInput(input, normalized);
  } catch (error) {
    if (!(error instanceof YamlCageError)) throw error;
    findings.push(findingFromError(error, 1));
    const stats = Object.freeze({
      bytes: byteSize,
      documents: 0,
      nodes: 0,
      maxDepth: 0,
      aliases: 0,
      expandedNodes: 0,
      warnings: 0
    });
    return Object.freeze({ safe: false, findings: freezeFindings(findings), stats });
  }

  let documents;
  try {
    documents = splitDocuments(text);
  } catch (error) {
    if (!(error instanceof YamlCageError)) throw error;
    findings.push(findingFromError(error, 1));
    const stats = Object.freeze({
      bytes: byteSize,
      documents: 0,
      nodes: 0,
      maxDepth: 0,
      aliases: 0,
      expandedNodes: 0,
      warnings: 0
    });
    return Object.freeze({ safe: false, findings: freezeFindings(findings), stats });
  }

  let droppedFindings = 0;
  const pushAuditFinding = (finding) => {
    if (findings.length < normalized.maxFindings) findings.push(finding);
    else droppedFindings += 1;
  };

  if (documents.length > normalized.maxDocuments) {
    pushAuditFinding({
      code: ERROR.MAX_DOCUMENTS,
      severity: 'error',
      message: 'YAML document count limit exceeded',
      document: normalized.maxDocuments + 1,
      limit: normalized.maxDocuments,
      actual: documents.length
    });
  }
  if (documents.length > 1 && !normalized.allowMultiDocument) {
    pushAuditFinding({
      code: ERROR.MULTI_DOCUMENT,
      severity: 'error',
      message: 'multi-document YAML stream detected',
      line: documents[1].startLine,
      column: 1,
      document: 2,
      actual: documents.length
    });
  }

  const scanned = scanYamlThreats(documents, normalized);
  droppedFindings += scanned.dropped;
  for (const finding of scanned.findings) {
    if (finding.code === ERROR.MERGE_KEY_FORBIDDEN && normalized.allowMergeKeys) continue;
    pushAuditFinding(finding);
  }

  const ctx = createContext(normalized);
  let parsedCount = 0;
  for (let index = 0; index < documents.length; index += 1) {
    try {
      parseDocument(documents[index], ctx, index + 1);
      parsedCount += 1;
    } catch (error) {
      if (!(error instanceof YamlCageError)) throw error;
      const finding = findingFromError(error, index + 1);
      const tokenIdentity = (item) => item.code + '|' + (item.key || '') + '|' + (item.anchor || '') + '|' + (item.alias || '') + '|' + (item.tag || '');
      const duplicate = findings.some((existing) => tokenIdentity(existing) === tokenIdentity(finding));
      if (!duplicate) pushAuditFinding(finding);
    }
  }
  droppedFindings += ctx.warningsTruncated;
  for (const warning of ctx.warnings) {
    const severity = normalized.strictNorwayScalars ? 'error' : 'warning';
    pushAuditFinding({ ...warning, severity });
  }
  if (droppedFindings > 0) {
    findings[normalized.maxFindings - 1] = {
      code: ERROR.MAX_FINDINGS,
      severity: 'error',
      message: 'audit finding count exceeded the reporting cap',
      limit: normalized.maxFindings,
      actual: normalized.maxFindings + droppedFindings
    };
  }
  const safe = !findings.some((finding) => finding.severity === 'error');
  const stats = Object.freeze({
    bytes: byteSize,
    documents: documents.length,
    nodes: ctx.nodes,
    maxDepth: ctx.maxDepthSeen,
    aliases: ctx.aliases,
    expandedNodes: ctx.expandedNodes,
    warnings: findings.filter((finding) => finding.severity === 'warning').length,
    parsedDocuments: parsedCount
  });
  return Object.freeze({ safe, findings: freezeFindings(findings), stats });
}

function serializerError(code, message, path, details) {
  throw new YamlCageError(code, message, { ...(details || {}), path });
}

function isDangerousOutputKey(key) {
  return DANGEROUS_KEYS.has(key);
}

function escapeDoubleQuotedString(value) {
  let output = '"';
  for (let index = 0; index < value.length; index += 1) {
    const code = value.charCodeAt(index);
    const ch = value[index];
    if (code >= 0xd800 && code <= 0xdbff) {
      const next = value.charCodeAt(index + 1);
      if (!(next >= 0xdc00 && next <= 0xdfff)) return null;
      output += ch + value[index + 1];
      index += 1;
      continue;
    }
    if (code >= 0xdc00 && code <= 0xdfff) return null;
    if (ch === '"') output += '\\"';
    else if (ch === '\\') output += '\\\\';
    else if (ch === '\n') output += '\\n';
    else if (ch === '\t') output += '\\t';
    else if (ch === '\r') output += '\\r';
    else if (code === 0x08) output += '\\b';
    else if (code === 0x0c) output += '\\f';
    else if (code === 0x0b) output += '\\x0b';
    else if (code < 0x20 || (code >= 0x7f && code <= 0x9f) || code === 0x2028 || code === 0x2029) {
      output += '\\u' + code.toString(16).padStart(4, '0');
    } else {
      output += ch;
    }
  }
  return output + '"';
}

const PLAIN_FORBIDDEN_START = new Set(['-', '?', ':', ',', '[', ']', '{', '}', '#', '&', '*', '!', '|', '>', "'", '"', '%', '@', '`']);
const YAML12_WORDS = new Set(['true', 'True', 'TRUE', 'false', 'False', 'FALSE', 'null', 'Null', 'NULL', '~']);
const NUMERIC_LOOKING = /^[+-]?(?:0[xX][0-9a-fA-F]+|0[oO][0-7]+|[0-9]+|(?:[0-9]+\.[0-9]*)|(?:\.[0-9]+)|(?:[0-9]+[eE][+-]?[0-9]+)|(?:[0-9]+\.[0-9]*[eE][+-]?[0-9]+)|(?:\.[0-9]+[eE][+-]?[0-9]+)|\.[nN][aA][nN]|\.[iI][nN][fF]|[+-]?\.[iI][nN][fF]|[+-]?(?:inf|Inf|INF|infinity|Infinity|INFINITY)|[nN][aA][nN])$/;
const YAML11_NUMERIC_LOOKING = /^[+-]?(?:0[bB][01_]+|[0-9][0-9_]+|[0-9]+(?::[0-5]?[0-9])+(?:\.[0-9_]*)?)$/;
const TIMESTAMP_LOOKING = /^[0-9]{4}-[0-9]{1,2}-[0-9]{1,2}(?:[Tt ][0-9]{1,2}:[0-9]{1,2}:[0-9]{1,2}(?:\.[0-9]+)?(?:[Zz]|[+-][0-9]{1,2}(?::?[0-9]{2})?)?)?$/;

function canUsePlainString(value) {
  if (value.length === 0) return false;
  if (value !== value.trim()) return false;
  if (value.endsWith(':') || value.startsWith('...')) return false;
  if (YAML12_WORDS.has(value) || YAML11_AMBIGUOUS_WORDS.has(value) || NUMERIC_LOOKING.test(value) || YAML11_NUMERIC_LOOKING.test(value) || TIMESTAMP_LOOKING.test(value)) return false;
  if (/^[0-9]/.test(value) && /^[+-]?0[0-9]+$/.test(value)) return false;
  if (PLAIN_FORBIDDEN_START.has(value[0])) return false;
  if (value.includes(': ') || value.includes(' #') || value.includes('\n') || value.includes('\r') || value.includes('\t')) return false;
  if (/[\[\]\{\},]/.test(value)) return false;
  for (let index = 0; index < value.length; index += 1) {
    const code = value.charCodeAt(index);
    if (code < 0x20 || (code >= 0x7f && code <= 0x9f)) return false;
    if (code >= 0xd800 && code <= 0xdbff) {
      const next = value.charCodeAt(index + 1);
      if (!(next >= 0xdc00 && next <= 0xdfff)) return false;
      index += 1;
      continue;
    }
    if (code >= 0xdc00 && code <= 0xdfff) return false;
  }
  return true;
}

function quoteYamlString(value) {
  if (canUsePlainString(value)) return value;
  const escaped = escapeDoubleQuotedString(value);
  if (escaped === null) return null;
  return escaped;
}

function validateSerializedString(value, path, options) {
  const length = utf8Length(value);
  if (length > options.maxStringLength) {
    serializerError(ERROR.MAX_STRING_LENGTH, 'string scalar length limit exceeded', path, {
      limit: options.maxStringLength,
      actual: length
    });
  }
  if (hasBidiControl(value)) {
    serializerError(ERROR.CONTROL_CHARACTER, 'strings with bidirectional control characters cannot be serialized', path);
  }
}

function formatScalar(value, path, options) {
  if (value === null) return 'null';
  if (value === true) return 'true';
  if (value === false) return 'false';
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) {
      serializerError(ERROR.UNSUPPORTED_VALUE, 'non-finite numbers cannot be serialized', path, { actual: String(value) });
    }
    return Object.is(value, -0) ? '-0' : String(value);
  }
  if (typeof value === 'string') {
    validateSerializedString(value, path, options);
    const quoted = quoteYamlString(value);
    if (quoted === null) {
      serializerError(ERROR.LONE_SURROGATE, 'strings with lone UTF-16 surrogates cannot be serialized', path);
    }
    return quoted;
  }
  serializerError(ERROR.UNSUPPORTED_VALUE, 'only null, booleans, finite numbers, strings, arrays, and plain objects can be serialized', path, {
    actual: typeof value
  });
}

const objectHasOwn = Object.prototype.hasOwnProperty;

function uninspectableValue(path) {
  serializerError(ERROR.UNSUPPORTED_VALUE, 'object properties cannot be inspected safely', path, { actual: 'uninspectable object' });
}

function assertSerializableShape(node, path) {
  const isArray = Array.isArray(node);
  let prototype;
  let symbols;
  try {
    prototype = Object.getPrototypeOf(node);
    symbols = Object.getOwnPropertySymbols(node);
  } catch {
    uninspectableValue(path);
  }
  if (!isArray && prototype !== null && prototype !== Object.prototype) {
    serializerError(ERROR.UNSUPPORTED_VALUE, 'only plain objects can be serialized', path, { actual: 'object' });
  }
  if (symbols.length > 0) {
    serializerError(ERROR.UNSUPPORTED_VALUE, 'objects with symbol keys cannot be serialized', path, { actual: 'symbol-keyed object' });
  }
}

function readOwnDataProperty(node, key, path) {
  let descriptor;
  try {
    descriptor = Object.getOwnPropertyDescriptor(node, key);
  } catch {
    uninspectableValue(path);
  }
  if (!descriptor) {
    serializerError(ERROR.UNSUPPORTED_VALUE, 'unassigned or inconsistent object properties cannot be serialized', path);
  }
  if (!objectHasOwn.call(descriptor, 'value')) {
    serializerError(ERROR.UNSUPPORTED_VALUE, 'accessor properties cannot be serialized', path, { actual: 'accessor property' });
  }
  return descriptor.value;
}

function validateOutputKey(key, path, options) {
  if (isDangerousOutputKey(key)) {
    serializerError(ERROR.PROTOTYPE_KEY, 'dangerous object keys cannot be serialized', path, { key });
  }
  const length = utf8Length(key);
  if (length > options.maxKeyLength) {
    serializerError(ERROR.MAX_KEY_LENGTH, 'mapping key length limit exceeded', path, {
      key,
      limit: options.maxKeyLength,
      actual: length
    });
  }
  if (hasBidiControl(key)) {
    serializerError(ERROR.CONTROL_CHARACTER, 'keys with bidirectional control characters cannot be serialized', path, { key });
  }
}

function objectEntriesForSerialization(node, options, path) {
  const entries = [];
  try {
    for (const key in node) {
      if (!objectHasOwn.call(node, key)) continue;
      if (entries.length >= options.maxKeys) {
        serializerError(ERROR.MAX_KEYS, 'mapping key count limit exceeded', path, {
          key,
          limit: options.maxKeys,
          actual: entries.length + 1
        });
      }
      validateOutputKey(key, path + '.' + key, options);
      entries.push({ key, value: readOwnDataProperty(node, key, path + '.' + key) });
    }
  } catch (error) {
    if (error instanceof YamlCageError) throw error;
    uninspectableValue(path);
  }
  return entries;
}

function canonicalArrayIndex(key, length) {
  if (!/^(?:0|[1-9][0-9]*)$/.test(key)) return false;
  const index = Number(key);
  return Number.isSafeInteger(index) && index >= 0 && index < length;
}

function validateArrayShape(node, options, path) {
  if (node.length > options.maxSequenceLength) {
    serializerError(ERROR.MAX_SEQUENCE_LENGTH, 'sequence length limit exceeded', path, {
      limit: options.maxSequenceLength,
      actual: node.length
    });
  }
  try {
    for (const key in node) {
      if (!objectHasOwn.call(node, key)) continue;
      if (!canonicalArrayIndex(key, node.length)) {
        serializerError(ERROR.UNSUPPORTED_VALUE, 'arrays with additional enumerable properties cannot be serialized', path, { actual: 'array object property' });
      }
    }
  } catch (error) {
    if (error instanceof YamlCageError) throw error;
    uninspectableValue(path);
  }
}

function readArrayElement(node, index, path) {
  if (!objectHasOwn.call(node, index)) {
    serializerError(ERROR.UNSUPPORTED_VALUE, 'arrays with unassigned elements cannot be serialized', path, { actual: 'sparse array' });
  }
  return readOwnDataProperty(node, String(index), path);
}

export function stringifySafeYaml(value, optionsInput) {
  const inputOptions = normalizeOptionsDetailed(optionsInput).options;
  const options = normalizeOptions({ ...inputOptions, allowMultiDocument: false });
  const parts = [];
  let outputBytes = 0;
  let nodes = 0;
  const emitLine = (indent, text) => {
    const line = ' '.repeat(indent) + text + '\n';
    outputBytes += utf8Length(line);
    if (outputBytes > options.maxOutputBytes) {
      serializerError(ERROR.MAX_OUTPUT_BYTES, 'YAML output byte limit exceeded', '$', {
        limit: options.maxOutputBytes,
        actual: outputBytes
      });
    }
    parts.push(line);
  };
  const countSerializerNode = (path) => {
    nodes += 1;
    if (nodes > options.maxNodes) {
      serializerError(ERROR.MAX_NODES, 'YAML node count limit exceeded', path, {
        limit: options.maxNodes,
        actual: nodes
      });
    }
  };
  const prepareCollection = (node, path, depth) => {
    assertSerializableShape(node, path);
    countSerializerNode(path);
    if (depth > options.maxDepth) {
      serializerError(ERROR.MAX_DEPTH, 'YAML nesting depth limit exceeded', path, {
        depth,
        limit: options.maxDepth,
        actual: depth
      });
    }
    if (Array.isArray(node)) {
      validateArrayShape(node, options, path);
      return { type: 'array', size: node.length, entries: null };
    }
    const entries = objectEntriesForSerialization(node, options, path);
    return { type: 'map', size: entries.length, entries };
  };

  if (value === null || typeof value !== 'object') {
    countSerializerNode('$');
    emitLine(0, formatScalar(value, '$', options));
    return parts.join('');
  }

  const rootMeta = prepareCollection(value, '$', 1);
  if (rootMeta.size === 0) {
    emitLine(0, rootMeta.type === 'array' ? '[]' : '{}');
    return parts.join('');
  }

  const ancestors = new Set([value]);
  const stack = [{ node: value, meta: rootMeta, index: 0, indent: 0, path: '$', depth: 1 }];
  while (stack.length > 0) {
    const frame = stack[stack.length - 1];
    if (frame.index >= frame.meta.size) {
      ancestors.delete(frame.node);
      stack.pop();
      continue;
    }

    if (frame.meta.type === 'array') {
      const index = frame.index;
      frame.index += 1;
      const childPath = frame.path + '[' + index + ']';
      const child = readArrayElement(frame.node, index, childPath);
      if (child !== null && typeof child === 'object') {
        if (ancestors.has(child)) serializerError(ERROR.CYCLE_DETECTED, 'cyclic values cannot be serialized', childPath);
        const childMeta = prepareCollection(child, childPath, frame.depth + 1);
        if (childMeta.size === 0) {
          emitLine(frame.indent, '- ' + (childMeta.type === 'array' ? '[]' : '{}'));
        } else {
          emitLine(frame.indent, '-');
          ancestors.add(child);
          stack.push({ node: child, meta: childMeta, index: 0, indent: frame.indent + 2, path: childPath, depth: frame.depth + 1 });
        }
      } else {
        countSerializerNode(childPath);
        emitLine(frame.indent, '- ' + formatScalar(child, childPath, options));
      }
      continue;
    }

    const entry = frame.meta.entries[frame.index];
    frame.index += 1;
    const key = entry.key;
    const childPath = frame.path + '.' + key;
    const encodedKey = quoteYamlString(key);
    if (encodedKey === null) {
      serializerError(ERROR.LONE_SURROGATE, 'keys with lone UTF-16 surrogates cannot be serialized', childPath, { key });
    }
    const child = entry.value;
    if (child !== null && typeof child === 'object') {
      if (ancestors.has(child)) serializerError(ERROR.CYCLE_DETECTED, 'cyclic values cannot be serialized', childPath);
      const childMeta = prepareCollection(child, childPath, frame.depth + 1);
      if (childMeta.size === 0) {
        emitLine(frame.indent, encodedKey + ': ' + (childMeta.type === 'array' ? '[]' : '{}'));
      } else {
        emitLine(frame.indent, encodedKey + ':');
        ancestors.add(child);
        stack.push({ node: child, meta: childMeta, index: 0, indent: frame.indent + 2, path: childPath, depth: frame.depth + 1 });
      }
    } else {
      countSerializerNode(childPath);
      emitLine(frame.indent, encodedKey + ': ' + formatScalar(child, childPath, options));
    }
  }
  return parts.join('');
}

export function createYamlCage(options) {
  const normalized = normalizeOptions(options);
  const mergeOptions = (overrides) => mergeNormalizedOptions(normalized, overrides);
  return Object.freeze({
    options: normalized,
    parse(input, overrides) {
      return parseSafeYaml(input, mergeOptions(overrides));
    },
    parseBytes(input, overrides) {
      return parseSafeYamlBytes(input, mergeOptions(overrides));
    },
    parseDocuments(input, overrides) {
      return parseSafeYamlDocuments(input, mergeOptions(overrides));
    },
    audit(input, overrides) {
      return auditYaml(input, mergeOptions(overrides));
    },
    stringify(input, overrides) {
      return stringifySafeYaml(input, mergeOptions(overrides));
    }
  });
}

const yamlcage = Object.freeze({
  YAMLCAGE_VERSION,
  YAMLCAGE_ERROR_CODES,
  YAML_CAGE_DEFAULT_OPTIONS,
  CODE,
  YamlCageError,
  parseSafeYaml,
  parseSafeYamlBytes,
  parseSafeYamlDocuments,
  auditYaml,
  stringifySafeYaml,
  createYamlCage
});

export default yamlcage;
